from three_lane_runner import main

if __name__ == "__main__":
    main()

"""Select a connected, marked three-lane Native highway section.

The selector returns map geometry and marking readback. It does not infer that
paint is physically visible in a camera or that a lane use is lawful.
"""

from math import hypot


def _xy(waypoint):
    location = waypoint.transform.location
    return float(location.x), float(location.y)


def _unit(waypoint):
    vector = waypoint.transform.get_forward_vector()
    norm = hypot(vector.x, vector.y)
    if norm < 0.8:
        raise ValueError('Map travel tangent unavailable')
    return vector.x / norm, vector.y / norm


def _marked(marking):
    if marking is None:
        return False
    kind = getattr(marking, 'type', marking)
    value = str(kind).lower()
    return bool(value) and 'none' not in value and 'unknown' not in value


def ordered_lanes(right_lane):
    """Read exactly three adjacent driving lanes, ordered for ego travel."""
    center = right_lane.get_left_lane()
    extreme_left = center.get_left_lane() if center is not None else None
    lanes = (right_lane, center, extreme_left)
    if any(lane is None or str(getattr(lane, 'lane_type', '')).lower().find('driving') < 0
           for lane in lanes):
        raise ValueError('Three adjacent driving lanes required')
    if len({(lane.road_id, lane.lane_id) for lane in lanes}) != 3 or len({lane.road_id for lane in lanes}) != 1:
        raise ValueError('Three adjacent lanes must share one road identity')
    def driving(lane):
        return lane is not None and 'driving' in str(getattr(lane, 'lane_type', '')).lower()
    if driving(right_lane.get_right_lane()) or driving(extreme_left.get_left_lane()):
        raise ValueError('Three-lane section has an additional mapped lane')
    tangent = _unit(right_lane)
    left = (-tangent[1], tangent[0])
    for first, second in zip(lanes, lanes[1:]):
        if first.lane_width <= 0 or second.lane_width <= 0:
            raise ValueError('Mapped lane width invalid')
        a, b = _xy(first), _xy(second)
        separation = (b[0] - a[0]) * left[0] + (b[1] - a[1]) * left[1]
        expected = (first.lane_width + second.lane_width) / 2
        if abs(separation - expected) > 0.45:
            raise ValueError('Mapped lane adjacency or ordering differs')
    if sum(a * b for a, b in zip(tangent, _unit(center))) < 0.95:
        raise ValueError('Center lane is not in ego travel direction')
    for lane in lanes:
        if not _marked(lane.left_lane_marking) or not _marked(lane.right_lane_marking):
            raise ValueError('Three clearly marked lanes lack map marking readback')
    return {'right': right_lane, 'center': center, 'extreme_left': extreme_left}


def select_route(world_map, *, direction='east', steps=12, spacing_m=2.5):
    """Find a same-road corridor; test both directions with direction parameter."""
    if direction not in ('east', 'west') or steps < 2 or spacing_m <= 0:
        raise ValueError('Three-lane route selector parameters invalid')
    for spawn in world_map.get_spawn_points():
        start = world_map.get_waypoint(spawn.location)
        if start is None or start.is_junction:
            continue
        forward = _unit(start)
        if (direction == 'east' and forward[0] <= 0.8) or (direction == 'west' and forward[0] >= -0.8):
            continue
        try:
            ordered_lanes(start)
        except ValueError:
            continue
        route = [start]
        for _ in range(steps):
            options = [waypoint for waypoint in route[-1].next(spacing_m)
                       if waypoint.road_id == start.road_id and waypoint.lane_id == start.lane_id
                       and not waypoint.is_junction]
            if not options:
                break
            try:
                ordered_lanes(options[0])
            except ValueError:
                break
            route.append(options[0])
        if len(route) == steps + 1:
            return route
    raise ValueError('No connected marked three-lane corridor in selected direction')


def section_readback(right_lane):
    lanes = ordered_lanes(right_lane)
    return {'road_id': right_lane.road_id,
            'lane_ids': {name: lane.lane_id for name, lane in lanes.items()},
            'lane_widths_m': {name: float(lane.lane_width) for name, lane in lanes.items()},
            'lane_directions_xy': {name: list(_unit(lane)) for name, lane in lanes.items()},
            'markings': {name: {'left': str(lane.left_lane_marking.type),
                                'right': str(lane.right_lane_marking.type)}
                         for name, lane in lanes.items()},
            'map_markings_verified': True,
            'physical_paint_visible': None,
            'legal_lane_status': None}

"""Original-frame occupancy of ordered three-lane highway geometry.

Map lane polygons and traffic direction are geometry sources. Clearly marked
lanes, posted allocation and safe passing distance require separate evidence.
"""

from hashlib import sha256
import json
from math import hypot, isfinite
from pathlib import Path

from shapely.geometry import Polygon


CONDITIONS = ('three_clearly_marked_lanes', 'passing_same_direction',
              'highway_clearly_visible', 'center_clear_safe_distance',
              'preparing_left_turn', 'center_allocated_same_direction',
              'allocation_sign_posted')
LANES = ('right', 'center', 'extreme_left')


def _load(path, label):
    path = Path(path)
    if not path.is_file() or not path.read_bytes():
        raise ValueError('Missing original source: ' + label)
    raw = path.read_bytes()
    try:
        value = json.loads(raw) if path.suffix == '.json' else [json.loads(line) for line in raw.splitlines()]
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError('Invalid original source: ' + label) from error
    return value, sha256(raw).hexdigest()


def _point(value):
    if not isinstance(value, list) or len(value) != 2:
        raise ValueError('Original lane point missing')
    try:
        xy = tuple(float(v) for v in value)
    except (TypeError, ValueError) as error:
        raise ValueError('Original lane point invalid') from error
    if not all(isfinite(v) for v in xy):
        raise ValueError('Original lane point invalid')
    return xy


def _polygon(points, label):
    if not isinstance(points, list) or len(points) < 4:
        raise ValueError('Original ' + label + ' polygon incomplete')
    shape = Polygon([_point(p) for p in points])
    if not shape.is_valid or shape.area <= 0:
        raise ValueError('Original ' + label + ' polygon invalid')
    return shape


def measure(frame_path, context_path):
    rows, frame_sha = _load(frame_path, 'three_lane_frames.jsonl')
    context, context_sha = _load(context_path, 'three_lane_context.json')
    if not isinstance(rows, list) or len(rows) < 2 or not isinstance(context, dict):
        raise ValueError('Original three-lane sources incomplete')
    conditions = {}
    for name in CONDITIONS:
        item = context.get(name)
        if not isinstance(item, dict) or 'value' not in item:
            raise ValueError('Three-lane condition missing: ' + name)
        value, source = item['value'], item.get('source_ref')
        if value is not None and (type(value) is not bool or not isinstance(source, str) or not source):
            raise ValueError('Known three-lane condition needs source: ' + name)
        if value is None and source is not None:
            raise ValueError('Unknown three-lane condition cannot cite verdict: ' + name)
        conditions[name] = {'value': value, 'source_ref': source}
    observations = []
    previous = None
    for row in rows:
        frame, time_s = row.get('frame'), row.get('time_s')
        if type(frame) is not int or type(time_s) not in (int, float) or not isfinite(time_s):
            raise ValueError('Original three-lane frame/time invalid')
        if previous is not None and (frame != previous[0] + 1 or abs(time_s - previous[1] - .05) > 1e-4):
            raise ValueError('Original three-lane frames are not joined at 20 Hz')
        previous = frame, time_s
        tangent = _point(row.get('road_travel_tangent_xy'))
        norm = hypot(*tangent)
        if norm < 1e-6:
            raise ValueError('Original three-lane travel direction degenerate')
        ego = _polygon(row.get('ego_corners_xy'), 'ego')
        lane_points = row.get('lane_polygons_xy')
        if not isinstance(lane_points, dict) or set(lane_points) != set(LANES):
            raise ValueError('Exactly three named original lane polygons required')
        lanes = {name: _polygon(lane_points[name], name) for name in LANES}
        def lateral(shape):
            c = shape.centroid
            return (tangent[0] * c.y - tangent[1] * c.x) / norm
        if not lateral(lanes['right']) < lateral(lanes['center']) < lateral(lanes['extreme_left']):
            raise ValueError('Original lane order differs from travel direction')
        fractions = {name: ego.intersection(shape).area / ego.area
                     for name, shape in lanes.items()}
        observations.append({'frame': frame, 'time_s': time_s,
                             'road_id': row.get('road_id'),
                             'body_lane_overlap_fraction': fractions,
                             'extreme_left_body_overlap': fractions['extreme_left'] > 0,
                             'center_body_overlap': fractions['center'] > 0})
    return {'format': 'worker-three-lane-observation',
            'sources': {'three_lane_frames.jsonl': frame_sha,
                        'three_lane_context.json': context_sha},
            'observations': observations, 'condition_context': conditions,
            'safe_distance_legal_judgment': None,
            'center_lane_exception_legal_judgment': None,
            'extreme_left_lane_legal_judgment': None}

"""Four synchronized original RGB source streams for three-lane probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-8, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown three-lane source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior three-lane camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original three-lane camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Right-half source encoder failed")


class ThreeLaneCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named three-lane source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original three-lane camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original three-lane camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Right-half source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original three-lane source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original three-lane camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

import sys
import unittest
from pathlib import Path
from types import SimpleNamespace as NS

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from three_lane_runner import CASE, check_config, control_step
from three_lane_camera import CAMERAS, ThreeLaneCameraCapture


def config():
    return {'selected_case_id': CASE, 'law_id': 'NRS-484B-223-2',
            'cell_id': 'C304406', 'actor': 'motor_vehicle_driver',
            'rate_hz': 20, 'frames': 160, 'duration_s': 8, 'lane_role': 'right',
            'cameras': [{'name': name} for name in CAMERAS]}


class ThreeLaneRunnerTests(unittest.TestCase):
    def test_exact_identity_and_four_cameras(self):
        check_config(config())
        wrong = config()
        wrong['selected_case_id'] = CASE.replace('right_baseline', 'center_default')
        with self.assertRaisesRegex(ValueError, 'identity'):
            check_config(wrong)
        center = config()
        center['selected_case_id'] = CASE.replace('right_baseline', 'center_default')
        center['lane_role'] = 'center'
        check_config(center)
        wrong = config()
        wrong['cameras'] = wrong['cameras'][:-1]
        with self.assertRaisesRegex(ValueError, 'Four named'):
            check_config(wrong)

    def test_feedback_targets_route_without_unbounded_control(self):
        control = control_step((0, 0), (1, 0), (0, 0), (10, 1))
        self.assertGreater(control['throttle'], 0)
        self.assertGreater(control['steer'], 0)
        self.assertLessEqual(control['steer'], 0.55)
        with self.assertRaisesRegex(ValueError, 'too close'):
            control_step((0, 0), (1, 0), (0, 0), (0.1, 0))

    def test_four_original_camera_sensors_are_spawned_and_frame_joined(self):
        sensors = []
        class Blueprint:
            def __init__(self):
                self.attributes = {}
            def set_attribute(self, key, value):
                self.attributes[key] = value
        class Sensor:
            def listen(self, callback):
                self.callback = callback
            def stop(self):
                self.stopped = True
            def destroy(self):
                self.destroyed = True
        class World:
            def get_blueprint_library(self):
                return NS(find=lambda name: Blueprint())
            def spawn_actor(self, blueprint, transform, attach_to):
                sensor = Sensor()
                sensors.append((sensor, blueprint, transform, attach_to))
                return sensor
        carla = NS(Transform=lambda location, rotation: NS(location=location, rotation=rotation),
                   Location=lambda *xyz: xyz, Rotation=lambda *xyz: xyz)
        writes = {name: [] for name in CAMERAS}
        sinks = {name: NS(write=lambda image, key=name: writes[key].append(image.frame))
                 for name in CAMERAS}
        capture = ThreeLaneCameraCapture(World(), carla, object(), sinks)
        self.assertEqual(len(sensors), 4)
        for name, (sensor, blueprint, _, _) in zip(CAMERAS, sensors):
            width, height = CAMERAS[name][2]
            self.assertEqual(blueprint.attributes['image_size_x'], str(width))
            sensor.callback(NS(frame=41, width=width, height=height))
        capture.wait_for_frame(41, timeout_s=0.1)
        self.assertEqual(capture.verify([41]), {name: 1 for name in CAMERAS})
        capture.close()
        self.assertTrue(all(sensor.stopped and sensor.destroyed for sensor, _, _, _ in sensors))


if __name__ == '__main__':
    unittest.main()
